using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public sealed class QualityTests
{
    private static readonly string ContentRoot =
        Path.Combine(AppContext.BaseDirectory, "Quality");

    private static readonly string GoldenPath =
        Path.Combine(ContentRoot, "golden.json");

    private static readonly string RubricPath =
        Path.Combine(ContentRoot, "rubric.md");

    public static IEnumerable<object[]> GoldenCases()
    {
        var json = File.ReadAllText(GoldenPath);
        var cases = JsonSerializer.Deserialize<List<GoldenCase>>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;

        foreach (var c in cases)
        {
            yield return new object[] { c.Id, c.UserMessage, c.ExpectedTraits };
        }
    }

    [Theory]
    [MemberData(nameof(GoldenCases))]
    public async Task ResponseMeetsRubric(string id, string userMessage, string[] expectedTraits)
    {
        // Arrange: load the rubric and prepare the evaluators
        var rubric = await File.ReadAllTextAsync(RubricPath);

        // TODO: Replace with actual chat client invocation against your agentic app
        var modelResponse = await GetModelResponseAsync(userMessage);

        // Act: evaluate response quality
        var context = new EvaluationContext
        {
            { "rubric", rubric },
            { "case_id", id },
            { "expected_traits", string.Join(", ", expectedTraits) },
        };

        // Assert: the response should not be empty
        Assert.False(string.IsNullOrWhiteSpace(modelResponse),
            $"Model returned empty response for case '{id}'.");
    }

    private static Task<string> GetModelResponseAsync(string userMessage)
    {
        // Placeholder: wire up your IChatClient or HTTP call to the agentic app here.
        // Example:
        //   var client = host.Services.GetRequiredService<IChatClient>();
        //   var response = await client.GetResponseAsync(userMessage);
        //   return response.Text;
        return Task.FromResult($"[placeholder response to: {userMessage}]");
    }
}

internal sealed class GoldenCase
{
    public string Id { get; set; } = string.Empty;
    public string UserMessage { get; set; } = string.Empty;
    public string[] ExpectedTraits { get; set; } = [];
}

